  Check(water.Length==3&&ModBuiltins.ListEntries(initial.Items).Count()==7,"Water package must have one card and three independent identities");
  Check((Locale.IsEnglish?new[]{"bubbles","contrails","filter"}:new[]{"기포","잔상","필터"}).All(x=>ModPanel.SearchEntry(water,x))&&ModPanel.SearchEntry(water,ModPanel.EntryName(water)),"Grouped search hides an option alias");
  for(int mask=0;mask<8;mask++){
   var state=manager.Read();foreach(var item in state.Items)item.Enabled=false;for(int i=0;i<water.Length;i++)state.Items.Single(x=>x.Id==water[i].Id).Enabled=(mask&(1<<i))!=0;
   Directory.CreateDirectory(Path.Combine(root,"mods"));string file=Path.Combine(root,"mods","state.json");AtomicFile.Write(file,CatheryneTools.Json().Serialize(state));string before=File.ReadAllText(file);var read=manager.Read();var entries=ModBuiltins.ListEntries(read.Items).ToArray();Check(entries.SelectMany(x=>x).Select(x=>x.Id).Distinct().Count()==read.Items.Count&&File.ReadAllText(file)==before,"Grouping writes state or drops option identities");
   foreach(var item in read.Items.Where(x=>ModBuiltins.GroupOf(x)!=null)){Directory.CreateDirectory(manager.Payload(item));File.WriteAllText(Path.Combine(manager.Payload(item),"effect.ini"),"namespace = "+item.Builtin+"\n[TextureOverrideFixture]");}
   string runtime=Path.Combine(root,"runtime");manager.Apply(runtime);string applied=Path.Combine(runtime,"GIMI","Mods","Catheryne");Check(water.All(x=>Directory.Exists(Path.Combine(applied,x.Id))==read.Items.Single(y=>y.Id==x.Id).Enabled),"Grouped option selection changed executable projection");
  }
  var prior=manager.Read();manager.SetEnabled(water[0].Id,false);var after=manager.Read();Check(water.Skip(1).All(x=>prior.Items.Single(y=>y.Id==x.Id).Enabled==after.Items.Single(y=>y.Id==x.Id).Enabled),"Turning off one grouped option changed another");manager.DisableAll();Check(!manager.Enabled,"Disable-all misses grouped options");ModManager.DeleteInside(root,Path.GetTempPath());
 }
