 static void PresentationContracts(){
  string root=Path.Combine(Path.GetTempPath(),"catheryne-mod-presentation-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
  try{
   string account=Path.Combine(root,"account.json");File.WriteAllText(account,"{\"format\":\"GOOD\",\"characters\":[{\"key\":\"Wanderer\",\"identity\":\"game:10000075\",\"gameId\":10000075,\"level\":90},{\"gameId\":10000999,\"names\":{\"ko\":\"새 캐릭터\"},\"level\":88}]}");new ProfileStore(root).Import("account",account);var manager=new ModManager(root,()=>false);Check(manager.Characters().Length==2,"Owned character list changed account facts");
   string source=Path.Combine(root,"anonymous");Directory.CreateDirectory(source);File.WriteAllText(Path.Combine(source,"mod.ini"),"[Constants]");var item=manager.Import(source,"character:game:10000999");Check(item.Target=="character:game:10000999"&&!item.Enabled,"Owned character context was discarded");manager.SetTarget(item.Id,"character:Wanderer");Check(manager.Read().Items.Single(x=>x.Id==item.Id).Target=="character:game:10000075","Catalog alias did not resolve to owned identity");manager.SetTarget(item.Id,"character:game:10000999");
   string named=Path.Combine(root,"새 캐릭터_의상");Directory.CreateDirectory(named);File.WriteAllText(Path.Combine(named,"mod.ini"),"[Constants]");Check(manager.Import(named).Target=="character:game:10000999","New owned character name needed a release mapping");
   string preview=Path.Combine(source,"preview.png");var bitmap=new System.Windows.Media.Imaging.RenderTargetBitmap(2,2,96,96,System.Windows.Media.PixelFormats.Pbgra32);var encoder=new System.Windows.Media.Imaging.PngBitmapEncoder();encoder.Frames.Add(System.Windows.Media.Imaging.BitmapFrame.Create(bitmap));using(var output=File.Create(preview))encoder.Save(output);
   manager.SetCover(item.Id,preview);item=manager.Read().Items.Single(x=>x.Id==item.Id);Check(ModArtwork.Local(item,manager)==Path.Combine(root,"mods","covers",item.Id+".png"),"Selected cover escaped private cover storage");Check(!Directory.GetFiles(manager.Payload(item),"*.png",SearchOption.AllDirectories).Any(),"Presentation image entered executable projection");
   string prior=File.ReadAllText(Path.Combine(root,"mods","state.json"));File.WriteAllText(preview,"invalid image");bool rejected=false;try{manager.SetCover(item.Id,preview);}catch{rejected=true;}Check(rejected&&File.ReadAllText(Path.Combine(root,"mods","state.json"))==prior,"Bad cover changed mod registry");
   item.Cover="../account.json";Check(ModArtwork.Local(item,manager)==null,"Unsafe cover path accepted");
  }finally{Directory.Delete(root,true);}
 }
 static void PackageContracts(){
