   Check(ModBuiltins.Catalog.Select(x=>x.Order).Distinct().Count()==ModBuiltins.Catalog.Length&&ModBuiltins.Catalog.All(x=>!string.IsNullOrEmpty(x.Author)&&!string.IsNullOrEmpty(x.Description)),"Builtin detail metadata or recommendation order missing");
   var ordered=ModBuiltins.Ordered(ModBuiltins.Catalog.Reverse().Select(x=>new ManagedMod{Id=x.Id,Builtin=x.Key,Name=x.Name}).Concat(new[]{new ManagedMod{Id="personal",Name="AAA"}})).ToArray();Check(ordered.First().Builtin=="dark-loading"&&ordered.Last().Id=="personal"&&ordered.Select(x=>x.Id).Distinct().Count()==ordered.Length,"Recommendation order changed builtin identity or personal grouping");
   string cache=Path.Combine(root,"mods","packages");Directory.CreateDirectory(cache);string archive=Path.Combine(cache,"fixture.zip");using(var zip=ZipFile.Open(archive,ZipArchiveMode.Create)){foreach(var entry in new[]{new[]{"README.txt","Original instructions"},new[]{"Module/DISABLED-Bubbles.ini","namespace = Bubbles"},new[]{"Module/Other.ini","namespace = Other"},new[]{"Module/Extras/UID.ini","namespace = Extra"}}){using(var writer=new StreamWriter(zip.CreateEntry(entry[0]).Open()))writer.Write(entry[1]);}}
   string stage=Path.Combine(root,"stage");Directory.CreateDirectory(stage);var selected=new BuiltinPackage{Folder="Selected",File="fixture",Hash=UpdateService.Hash(archive),Source="https://example.invalid/fixture",Credit="Fixture",SelectPath="Module/DISABLED-Bubbles.ini"};ModBuiltins.Unpack(root,stage,selected,null);string folder=Path.Combine(stage,"Selected");Check(Directory.GetFiles(folder,"*.ini",SearchOption.AllDirectories).Length==1&&File.ReadAllText(Path.Combine(folder,"Bubbles.ini"))=="namespace = Bubbles"&&File.ReadAllText(Path.Combine(folder,"README.txt"))=="Original instructions","Selected module changed bytes or enabled unrelated optional effects");
   var full=new BuiltinPackage{Folder="Full",File="fixture",Hash=selected.Hash,Source=selected.Source,Credit="Fixture",SelectPath="Module",DisabledFolder="Extras"};ModBuiltins.Unpack(root,stage,full,null);Check(File.Exists(Path.Combine(stage,"Full","Other.ini"))&&File.Exists(Path.Combine(stage,"Full","DISABLED_Extras","UID.ini"))&&!Directory.Exists(Path.Combine(stage,"Full","Module")),"Vendor wrapper or optional extras projection changed relative module layout");
   string before=File.ReadAllText(Path.Combine(stage,"Full","Other.ini"));var bad=new BuiltinPackage{Folder="Bad",File="fixture",Hash=selected.Hash,Source=selected.Source,Credit="Fixture",SelectPath="../escape.ini"};bool rejected=false;try{ModBuiltins.Unpack(root,stage,bad,null);}catch(InvalidDataException){rejected=true;}Check(rejected&&before==File.ReadAllText(Path.Combine(stage,"Full","Other.ini")),"Package content selection escaped its folder");
  }finally{Directory.Delete(root,true);}
 }
 static void BindingContracts(){
  string root=Path.Combine(Path.GetTempPath(),"mod-keys-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{
   string source=Path.Combine(root,"fixture");Directory.CreateDirectory(source);string original="; original\r\n\r\nnamespace = Fixture\r\n[KeyToggle]\r\ncondition = $active\r\nkey = no_modifiers F11 ; preserve comment\r\nkey = XB_A\r\nback = NO_ALT CTRL F11\r\n\r\n[CommandListFixture]\r\nkey = F3\r\n";File.WriteAllText(Path.Combine(source,"effect.ini"),original);string disabled=Path.Combine(source,"DISABLED_Optional");Directory.CreateDirectory(disabled);File.WriteAllText(Path.Combine(disabled,"other.ini"),"[KeyDisabled]\nkey = F11");var manager=new ModManager(root,()=>false);var item=manager.Import(source);var keys=ModBindings.Read(item,manager);Check(keys.Length==3&&keys[0].Line==5,"Binding parser includes disabled INIs or non-Key command sections");Check(!ModBindings.CanEdit(keys[1])&&ModBindings.CanEdit(keys[0]),"Unknown controller syntax must stay read-only");
   Check(ModBindings.Overlap("f11","ctrl VK_F11")&&!ModBindings.Overlap("no_modifiers f11","ctrl F11")&&ModBindings.Overlap("VK_OEM_PLUS","0xBB")&&!ModBindings.Overlap("Alt 0","no_alt 0"),"Modifier wildcard overlap or key aliases are incorrect");
   string captured=ModBindings.Capture(System.Windows.Input.Key.F12,System.Windows.Input.ModifierKeys.Control);Check(ModBindings.Display(captured)=="Ctrl+F12"&&!ModBindings.Overlap(captured,"no_modifiers F12"),"Captured bindings must forbid unspecified modifiers");
   manager.SetEnabled(item.Id,true);string runtime=ModIntegration.ManagedRoot(root);Directory.CreateDirectory(Path.Combine(runtime,"Resources","Bin"));File.WriteAllText(Path.Combine(runtime,"Resources","Bin","XXMI Launcher.exe"),"");manager.Apply(runtime);string signature=manager.Read().AppliedSignature;manager.SetKey(item.Id,keys[0],captured);Check(manager.Pending&&manager.Read().Items.Single(x=>x.Id==item.Id).Keys.Count==1,"Key override must be canonical and pending");manager.Apply(runtime);string output=File.ReadAllText(Path.Combine(runtime,"GIMI","Mods","Catheryne",item.Id,"effect.ini"));Check(output.Contains("key = "+captured+" ; preserve comment")&&output.Contains("key = XB_A")&&output.Contains("back = NO_ALT CTRL F11")&&output.Contains("condition = $active"),"Projection changed unrelated binding, condition, or comment");Check(File.ReadAllText(Path.Combine(manager.Payload(item),"effect.ini"))==original,"Original mod bytes must remain unchanged");
   keys=ModBindings.Read(manager.Read().Items.Single(x=>x.Id==item.Id),manager);manager.SetKey(item.Id,keys[2],"no_modifiers F9");manager.Apply(runtime);output=File.ReadAllText(Path.Combine(runtime,"GIMI","Mods","Catheryne",item.Id,"effect.ini"));Check(output.Contains("back = no_modifiers F9")&&output.Contains(captured),"Independent bindings overwrite one another");manager.SetKey(item.Id,keys[0],null);Check(manager.Read().Items.Single(x=>x.Id==item.Id).Keys.Count==1,"Reset cleared other overrides");manager.SetKey(item.Id,keys[2],null);Check(ModManager.Signature(manager.Read())==signature,"Reset failed to restore the original signature");
